window.RP_SESSION={"id":"S-2a568580c499","messages":[{"id":"RP-II-0067729","time":"2026-03-23T13:57:00+09:00","room":"RP II","name":"캐너리 지엘리히","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 와서 쿠키 드세요! \"\n\n캐너리 지엘리히는 요새 어수선한 길드의 분위기에도 굴하지 않고 꿋꿋하게 길드원들의 기분을 나아지게 하기 위해 최선을 다하고 있다. 직접 딴 베리를 말려 얹은 달콤한 오트밀 쿠키를 주기적으로 구워서 나눠주는 것은 그 일부겠지. 자그마한 손으로 새빨간 산딸기를 따와서 화덕에 넣고 구운, 적당히 상큼달콤한 쿠키라면. 부드럽고 아름다운 그의 미소 만큼이나 사람의 기분을 좋아지게 만들기 충분할테니.\n\n@🧪","characters":["P-ec8583137a09"]},{"id":"RP-II-0067730","time":"2026-03-23T13:58:00+09:00","room":"RP II","name":"혼","profile":"🧪","identity":"reviewed","type":"dialogue","body":"\" 쿠키라..-.. \" \n\n실험용 쥐들에게 선물이나 해줄까나?.. 라는 생각으로 천천히 너의 앞으로 저벅 걸어와 \n\n\" 한 봉정도만 주실래요?~ \"","characters":["P-42d5d8f8594d"]},{"id":"RP-II-0067731","time":"2026-03-23T14:02:00+09:00","room":"RP II","name":"캐너리 지엘리히","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여기요, 혼 씨. 오랜만인 것 같네요! \"\n\n새하얗고 찬란한 순백의 머리칼과 아름답고 신비롭게 빛나는 오색빛 눈동자를 가진 사람. 혼. 자주 보이는 사람은 아니지만 언제나 친절하고 믿음직한 느낌을 주어서 캐너리 지엘리히는 그가 좋은 동료라고 생각한다.\n\n\" 지난번에는 스모어였는데, 이번에는 산딸기를 얹은 오트밀 쿠키에요. 마음에 드셨으면 좋겠네요! \"","characters":["P-ec8583137a09"]},{"id":"RP-II-0067732","time":"2026-03-23T22:03:00+09:00","room":"RP II","name":"캐너리 지엘리히","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-ec8583137a09"]},{"id":"RP-II-0067733","time":"2026-03-23T22:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
